/* eslint-disable */
import React from "react";
import { Link } from "react-router-dom";

import IndexNavbar from "components/Navbars/IndexNavbar.js";
import Footer from "components/Footers/Footer.js";

// Si ton alias "assets/..." douteux, remplace par "../assets/img/bg1.png" ou "../../assets/img/bg1.png"
import HeroImage from "assets/img/bg1.png";

export default function Index() {
  return (
    <>
      <IndexNavbar fixed />

      {/* HERO : sous la navbar, image + filtre marron + contenu */}
      <section
        className="relative mt-16 md:mt-20 h-screen max-h-860-px flex items-center"
        style={{
          // Couche marron (#6B140F) semi-transparente + image bg1 dessous
          backgroundImage: `linear-gradient(rgba(107, 20, 15, 0.6), rgba(107, 20, 15, 0.6)), url(${HeroImage})`,
          backgroundSize: "cover",
          backgroundPosition: "center 30%", // baisse un peu l'image; ajuste si besoin
          backgroundRepeat: "no-repeat",
          // fallback au cas où l'image ne charge pas
          backgroundColor: "#6B140F",
        }}
      >
        <div className="container mx-auto relative z-10 flex flex-wrap items-center">
          <div className="w-full lg:w-6/12 px-4">
            <h1 className="font-semibold text-4xl md:text-5xl text-white">
              Dalal ak jàamm
            </h1>
            <p className="mt-5 text-lg leading-relaxed text-white max-w-xl">
              Mame Samba
            </p>
          </div>
        </div>
      </section>


      {/* FEATURES */}
      <section id="features" className="py-24 bg-blueGray-50">
        <div className="container mx-auto px-4">
          <div className="text-center max-w-3xl mx-auto">
            <h2 className="text-3xl md:text-4xl font-semibold text-blueGray-800">
              Ce que vous obtenez
            </h2>
            <p className="text-blueGray-500 mt-4">
              Un starter propre, réactif, et extensible pour présenter votre produit/service.
            </p>
          </div>
        </div>
      </section>

      <Footer />
    </>
  );
}
